/*
 * Host cross-check for the shared x86 memory read body,
 * `X86_SIM_L_READ_MEM_VALUE`.
 *
 * Part 1 verifies the generated dispatch contract KPROG_X86_MEM_READ_SRC
 * from generated/x86_mem_dispatch.h against an independent oracle that
 * restates the read body's chain from the addressing fields rather than from
 * the macro's branch order.
 *
 * Part 2 drives the generated offset contract (KPROG_X86_MEM_OFFSET) and the
 * generated byte-ladder load contract (KPROG_X86_MEM_LOAD) together with the
 * dispatch over a deterministic memory/register/stack model, choosing the
 * value source from the generated contract, and cross-checks every result
 * against a hand-written model of the read body.
 *
 * The point of this oracle is the x86-specific dispatch asymmetry: the first
 * test in the read body is *register identity* — is the base the stack pointer
 * — not a memory tag. So a stack-pointer base reads through the stack helper
 * at any width and whatever its tag, while an ABI-tagged base reaches the
 * 64-bit pointer load only at width 64 and otherwise takes the ordinary load.
 * There is no reloc arm and no per-arm result tag in this read body: the ABI
 * packet tag refinement lives in `X86_SIM_L_EXEC_MOV_LOAD`, not here.
 *
 * Build/run:
 *   cd native-sim/formal
 *   cc -Wall -Wextra -O2 -I. test_x86_mem_read_dispatch_host.c -o /tmp/t_mrd && /tmp/t_mrd
 */
typedef unsigned char __u8;
typedef unsigned short __u16;
typedef unsigned int __u32;
typedef unsigned long long __u64;
typedef signed char __s8;
typedef short __s16;
typedef int __s32;
typedef signed long long __s64;

#define X86_WIDTH_8 1U
#define X86_WIDTH_16 2U
#define X86_WIDTH_32 4U
#define X86_WIDTH_64 8U

#define X86_REG_NONE 0xffU
#define X86_RSP 4U

#define X86_SIM_TAG_SCALAR 0U
#define X86_SIM_TAG_ABI 1U
#define X86_SIM_TAG_STACK 4U

/* The read body resolves its memory offset through the aux decoder the
 * simulator defines in x86_sim.h. Restate the three tiny decoders here so the
 * oracle exercises the same AUX encoding the sim uses. */
#define X86_MEM_AUX(INDEX, SCALE_LOG2)                                      \
	(((__u32)(INDEX) & 0xffU) | (((__u32)(SCALE_LOG2) & 0xffU) << 8))
#define X86_MEM_AUX_INDEX(AUX) ((__u8)((AUX) & 0xffU))
#define X86_MEM_AUX_SCALE_LOG2(AUX) ((__u8)(((AUX) >> 8) & 0xffU))

#include "generated/x86_mem_dispatch.h"
#include "generated/x86_mem_offset.h"
#include "generated/x86_mem_access.h"

#include <stdint.h>
#include <stdio.h>
#include <string.h>

/* ------------------------------------------------------------------ */
/* A deterministic register file, memory and stack model.             */
/*                                                                     */
/* Register "pointers" are stored as byte offsets into `oracle_mem` so */
/* the model stays inside the array at every address it forms.         */
/* ------------------------------------------------------------------ */

#define ORACLE_BYTES 4096
#define ORACLE_STACK_BYTES 64U

static __u8 oracle_mem[ORACLE_BYTES];
static __u8 oracle_stack[ORACLE_STACK_BYTES];

/* The 16 GPR slots the read body indexes, in X86_SIM_L_FOR_EACH_GPR order:
 * rax rcx rdx rbx rsp rbp rsi rdi r8..r15. */
struct oracle_reg {
	__u64 value;
	__u8 tag;
};

static struct oracle_reg oracle_regs[16];

static __u64 oracle_synthetic(__u64 index)
{
	return (__u8)((index * 131U + 17U) ^ (index >> 5));
}

static void oracle_reset(void)
{
	unsigned i;
	__u64 j;

	for (i = 0; i < 16; i++) {
		oracle_regs[i].value = 0;
		oracle_regs[i].tag = X86_SIM_TAG_SCALAR;
	}
	for (j = 0; j < ORACLE_BYTES; j++)
		oracle_mem[j] = (__u8)oracle_synthetic(j);
	for (j = 0; j < ORACLE_STACK_BYTES; j++)
		oracle_stack[j] = (__u8)oracle_synthetic(j + 7U);
}

/* ------------------------------------------------------------------ */
/* Hand-written models, independent of the macros under test.          */
/* ------------------------------------------------------------------ */

static int oracle_src(int base_is_rsp, int base_tag, int width)
{
	if (base_is_rsp)
		return KPROG_X86_MEM_SRC_STACK;
	if (base_tag == X86_SIM_TAG_ABI && width == X86_WIDTH_64)
		return KPROG_X86_MEM_SRC_ABI_PTR_LOAD;
	return KPROG_X86_MEM_SRC_NORMAL_LOAD;
}

/* Explicit byte ladder, never the macro's shift form. */
static __u64 oracle_load(__u64 addr, unsigned width)
{
	__u64 v = 0;
	unsigned i;

	for (i = 0; i < width; i++)
		v |= (__u64)oracle_mem[(addr + i) % ORACLE_BYTES] << (8 * i);
	return v;
}

static __u64 oracle_stack_load(__s64 off, unsigned width)
{
	__u32 index = (__u32)(off + ORACLE_STACK_BYTES);
	__u64 v = 0;
	unsigned i;

	for (i = 0; i < width; i++)
		v |= (__u64)oracle_stack[(index + i) % ORACLE_STACK_BYTES]
		     << (8 * i);
	return v;
}

static __u64 oracle_ptr_load(__u64 addr)
{
	void *p;

	memcpy(&p, &oracle_mem[addr % ORACLE_BYTES], sizeof(p));
	return (__u64)(uintptr_t)p;
}

/* ------------------------------------------------------------------ */
/* Part 1: the generated dispatch contract vs. the hand-written oracle. */
/* ------------------------------------------------------------------ */

static unsigned part1(void)
{
	static const unsigned widths[4] = {X86_WIDTH_8, X86_WIDTH_16,
					   X86_WIDTH_32, X86_WIDTH_64};
	static const __u8 tags[5] = {X86_SIM_TAG_SCALAR, X86_SIM_TAG_ABI,
				     X86_SIM_TAG_STACK, 0x80U, 0xffU};
	unsigned cases = 0;
	unsigned ti, wi;
	int bi;

	for (bi = 0; bi < 2; bi++) {
		for (ti = 0; ti < 5; ti++) {
			for (wi = 0; wi < 4; wi++) {
				int got = KPROG_X86_MEM_READ_SRC(
					bi, tags[ti], widths[wi]);
				int want = oracle_src(bi, tags[ti],
						      widths[wi]);

				if (got != want) {
					fprintf(stderr,
						"dispatch mismatch rsp=%d tag=%u w=%u got=%d want=%d\n",
						bi, tags[ti], widths[wi], got,
						want);
					return 0;
				}
				cases++;
			}
		}
	}

	/* Register identity overrides tag: an ABI-tagged stack pointer at any
	 * width must select the stack read. */
	for (wi = 0; wi < 4; wi++) {
		if (KPROG_X86_MEM_READ_SRC(1, X86_SIM_TAG_ABI, widths[wi]) !=
		    KPROG_X86_MEM_SRC_STACK) {
			fprintf(stderr, "rsp must override abi tag w=%u\n",
				widths[wi]);
			return 0;
		}
		cases++;
	}

	/* Off width 64 the ABI tag never widens to a pointer load. */
	for (wi = 0; wi < 3; wi++) {
		if (KPROG_X86_MEM_READ_SRC(0, X86_SIM_TAG_ABI, widths[wi]) !=
		    KPROG_X86_MEM_SRC_NORMAL_LOAD) {
			fprintf(stderr, "abi off width 64 widened w=%u\n",
				widths[wi]);
			return 0;
		}
		cases++;
	}

	/* Every arm is reachable. */
	if (KPROG_X86_MEM_READ_SRC(1, X86_SIM_TAG_SCALAR, X86_WIDTH_8) !=
		    KPROG_X86_MEM_SRC_STACK ||
	    KPROG_X86_MEM_READ_SRC(0, X86_SIM_TAG_ABI, X86_WIDTH_64) !=
		    KPROG_X86_MEM_SRC_ABI_PTR_LOAD ||
	    KPROG_X86_MEM_READ_SRC(0, X86_SIM_TAG_SCALAR, X86_WIDTH_8) !=
		    KPROG_X86_MEM_SRC_NORMAL_LOAD) {
		fprintf(stderr, "dispatch arm unreachable\n");
		return 0;
	}
	cases += 3;

	return cases;
}

/* ------------------------------------------------------------------ */
/* Part 2: dispatch + offset + load contracts vs. the read-body model.  */
/*                                                                     */
/* `contract_value` picks its value source from the generated dispatch  */
/* contract and computes the offset and the ordinary load through the   */
/* generated offset and memory-access contracts. `model_value` is the   */
/* hand-written read body. They must agree bit for bit.                 */
/* ------------------------------------------------------------------ */

static __u64 contract_value(int base_index, unsigned width, __u64 imm,
			    __u32 aux, int store_disp, __u64 index_value)
{
	__u8 tag = oracle_regs[base_index].tag;
	unsigned mem_width = width ? width : X86_WIDTH_64;
	__s64 disp = store_disp ? (__s32)(imm >> 32) : (__s64)imm;
	__s64 off;
	__u64 base_ptr = oracle_regs[base_index].value;
	__u64 addr;
	int src;

	off = KPROG_X86_MEM_OFFSET(aux, disp, index_value,
				   X86_MEM_AUX_INDEX(aux) != X86_REG_NONE);
	addr = base_ptr + (__u64)off;
	src = KPROG_X86_MEM_READ_SRC(base_index == X86_RSP, tag, mem_width);

	if (src == KPROG_X86_MEM_SRC_STACK)
		return oracle_stack_load((__s64)base_ptr + off, mem_width);
	if (src == KPROG_X86_MEM_SRC_ABI_PTR_LOAD)
		return oracle_ptr_load(addr);
	return KPROG_X86_MEM_LOAD(&oracle_mem[addr % ORACLE_BYTES], mem_width);
}

static __u64 model_value(int base_index, unsigned width, __u64 imm,
			 __u32 aux, int store_disp, __u64 index_value)
{
	__u8 tag = oracle_regs[base_index].tag;
	unsigned mem_width = width ? width : X86_WIDTH_64;
	__s64 disp = store_disp ? (__s32)(imm >> 32) : (__s64)imm;
	__s64 off = disp;
	__u64 base_ptr = oracle_regs[base_index].value;

	if (X86_MEM_AUX_INDEX(aux) != X86_REG_NONE)
		off += (__s64)(index_value << X86_MEM_AUX_SCALE_LOG2(aux));

	if (base_index == X86_RSP)
		return oracle_stack_load((__s64)base_ptr + off, mem_width);
	if (tag == X86_SIM_TAG_ABI && mem_width == X86_WIDTH_64)
		return oracle_ptr_load(base_ptr + (__u64)off);
	return oracle_load(base_ptr + (__u64)off, mem_width);
}

static unsigned part2(void)
{
	static const unsigned widths[4] = {X86_WIDTH_8, X86_WIDTH_16,
					   X86_WIDTH_32, X86_WIDTH_64};
	static const __u8 tags[4] = {X86_SIM_TAG_SCALAR, X86_SIM_TAG_ABI,
				     X86_SIM_TAG_STACK, 0x80U};
	unsigned cases = 0;
	unsigned ti, wi;
	int bi, di, si;

	for (bi = 0; bi < 16; bi++) {
		for (ti = 0; ti < 4; ti++) {
			for (wi = 0; wi < 4; wi++) {
				for (di = -3; di <= 3; di++) {
					for (si = 0; si < 2; si++) {
						__u64 imm;
						__u64 got, want;

						imm = si ?
							((__u64)(__u32)(di & 3)
							 << 32) :
							(__u64)(__s64)di;
						oracle_reset();
						oracle_regs[bi].value =
							512 + 8 * (unsigned)bi;
						oracle_regs[bi].tag = tags[ti];
						if (bi == X86_RSP) {
							/* Keep the stack
							 * pointer 8-aligned so
							 * the 64-bit fast path
							 * and the byte ladder
							 * agree. */
							oracle_regs[bi].tag =
								X86_SIM_TAG_ABI;
							oracle_regs[bi].value =
								ORACLE_STACK_BYTES / 2;
						}

						got = contract_value(bi,
							widths[wi], imm, 0U, si,
							0);
						want = model_value(bi,
							widths[wi], imm, 0U, si,
							0);
						if (got != want) {
							fprintf(stderr,
								"read mismatch reg=%u tag=%u w=%u imm=%llx sd=%d got=%llx want=%llx\n",
								bi, tags[ti],
								widths[wi],
								(unsigned long long)imm,
								si,
								(unsigned long long)got,
								(unsigned long long)want);
							return 0;
						}
						cases++;
					}
				}
			}
		}
	}

	/* Indexed addressing: the AUX index participates through the offset
	 * contract, at each scale, for a fixed non-stack base. */
	{
		static const __u8 scales[4] = {0U, 1U, 2U, 3U};
		unsigned si;

		for (si = 0; si < 4; si++) {
			for (wi = 0; wi < 4; wi++) {
				__u32 aux = X86_MEM_AUX(0U, scales[si]);
				__u64 got, want;

				oracle_reset();
				oracle_regs[1].value = 1024;
				oracle_regs[1].tag = X86_SIM_TAG_SCALAR;

				got = contract_value(1, widths[wi], 4U, aux,
						     0, 3U);
				want = model_value(1, widths[wi], 4U, aux, 0,
						   3U);
				if (got != want) {
					fprintf(stderr,
						"indexed read mismatch scale=%u w=%u got=%llx want=%llx\n",
						scales[si], widths[wi],
						(unsigned long long)got,
						(unsigned long long)want);
					return 0;
				}
				cases++;
			}
		}
	}

	return cases;
}

int main(void)
{
	unsigned c1 = part1();
	unsigned c2;

	if (c1 == 0)
		return 1;
	c2 = part2();
	if (c2 == 0)
		return 1;

	printf("x86 mem read dispatch host cross-check: OK (%u cases)\n",
	       c1 + c2);
	return 0;
}
